_EXPECTED_LOCALES = {code for code, _label in LANGUAGE_OPTIONS if code != "en"}
if set(_FEEDBACK_ROWS) != _EXPECTED_LOCALES | {"ha"}:
    raise ValueError(
        "Help-hub feedback catalogs must cover every non-English locale"
    )
if len(HELP_HUB_FEEDBACK_KEYS) != 29 or len(set(HELP_HUB_FEEDBACK_KEYS)) != 29:
    raise ValueError("Help-hub feedback sources must be exactly 29 unique keys")

HELP_HUB_FEEDBACK_CATALOGS: dict[str, dict[str, str]] = {
    locale: dict(zip(HELP_HUB_FEEDBACK_KEYS, row.split("¦"), strict=True))
    for locale, row in _FEEDBACK_ROWS.items()
}

for _locale, _entries in HELP_HUB_FEEDBACK_CATALOGS.items():
    if set(_entries) != set(HELP_HUB_FEEDBACK_KEYS):
        raise ValueError(
            f"Help-hub feedback source coverage is incomplete: {_locale}"
        )
    for _source, _translation in _entries.items():
        if not _translation.strip() or _translation == _source:
            raise ValueError(
                f"Missing help-hub feedback translation: {_locale}: {_source}"
            )
        if Counter(
            re.findall(r"\{([A-Za-z][A-Za-z0-9_]*)\}", _source)
        ) != Counter(re.findall(r"\{([A-Za-z][A-Za-z0-9_]*)\}", _translation)):
            raise ValueError(
                f"Help-hub feedback template slots differ: {_locale}: {_source}"
            )
